using Microsoft.AspNetCore.Mvc;
using ZainRecharge.Application.Recharges;

namespace ZainRecharge.Api.Controllers;

[ApiController]
[Route("api/recharge")]
public class RechargeController(IRechargeService rechargeService) : ControllerBase
{
    /// <summary>Recharge a mobile number. The transaction id is generated by the system.</summary>
    [HttpPost]
    [ProducesResponseType<RechargeResponse>(StatusCodes.Status201Created)]
    [ProducesResponseType<RechargeResponse>(StatusCodes.Status202Accepted)]
    [ProducesResponseType<RechargeResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status400BadRequest)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status502BadGateway)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status503ServiceUnavailable)]
    public async Task<IActionResult> Create(
        [FromBody] CreateRechargeRequest request, CancellationToken cancellationToken)
    {
        var result = await rechargeService.CreateAsync(request, cancellationToken);
        var recharge = result.Recharge;

        return result.Outcome switch
        {
            RechargeOutcome.Completed =>
                CreatedAtAction(nameof(GetById), new { id = recharge.Id }, recharge),            // 201
            RechargeOutcome.Declined =>
                Ok(recharge),                                                    // 200
            RechargeOutcome.Unknown =>
                Accepted($"/api/recharge/{recharge.Id}", recharge),                               // 202
            RechargeOutcome.ProviderUnavailable =>
                ProviderProblem(StatusCodes.Status503ServiceUnavailable,
                    "The payment provider is unavailable.", recharge),                            // 503
            _ =>
                ProviderProblem(StatusCodes.Status502BadGateway,
                    "The payment provider returned an error.", recharge)                          // 502
        };
    }

    /// <summary>Get one recharge by its id.</summary>
    [HttpGet("{id:int}")]
    [ProducesResponseType<RechargeResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status400BadRequest)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<RechargeResponse>> GetById(int id, CancellationToken cancellationToken) =>
        Ok(await rechargeService.GetByIdAsync(id, cancellationToken));

    /// <summary>List the recharges of a mobile number, newest first.</summary>
    [HttpGet("history/{mobileNumber}")]
    [ProducesResponseType<RechargeHistoryResponse>(StatusCodes.Status200OK)]
    [ProducesResponseType<ProblemDetails>(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<RechargeHistoryResponse>> GetHistory(
        string mobileNumber,
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 20,
        CancellationToken cancellationToken = default) =>
        Ok(await rechargeService.GetHistoryAsync(mobileNumber, page, pageSize, cancellationToken));

    // 502 and 503 are errors, so they use the standard error shape. The extra fields
    // tell the caller which recharge this was, so it can look it up later.
    private ObjectResult ProviderProblem(int statusCode, string title, RechargeResponse recharge)
    {
        var problem = ProblemDetailsFactory.CreateProblemDetails(
            HttpContext, statusCode: statusCode, title: title, detail: recharge.FailureReason);

        problem.Extensions["id"] = recharge.Id;
        problem.Extensions["transactionId"] = recharge.TransactionId;
        problem.Extensions["rechargeStatus"] = recharge.Status;

        if (statusCode == StatusCodes.Status503ServiceUnavailable)
            Response.Headers.RetryAfter = "30"; // seconds, a polite hint for the caller

        return new ObjectResult(problem) { StatusCode = statusCode };
    }
}
